interface SoundBuffer {
/** Play this sound effect and let the rest of your code continue. */
//% blockId=play_method block="play %soundeffect" blockNamespace=music color="#f368e0" group="Synthesizer"
play(): void;
}

interface SoundBuffer {
/** Play this sound effect and wait until it finishes before continuing. */
//% blockId=play_until_done_method block="play %soundeffect until done" blockNamespace=music color="#f368e0" group="Synthesizer"
playUntilDone(): void;
}

interface SoundBuffer {
/** Repeat this sound effect until its stop block is used. */
//% blockId=loop_method block="play %soundeffect until stopped" blockNamespace=music color="#f368e0" group="Synthesizer"
loop(): void;
}

interface SoundBuffer {
/** Stop this sound effect's repeating playback. */
//% blockId=stop_method block="stop %soundeffect" blockNamespace=music color="#f368e0" group="Synthesizer"
stop(): void;
}

